<script>document.addEventListener('DOMContentLoaded',function(){var clock=document.querySelector('[data-ops-dubai-clock]');function updateDubaiClock(){if(!clock)return;clock.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Dubai',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true}).format(new Date()).replace(',', '');}updateDubaiClock();setInterval(updateDubaiClock,30000);if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('[data-count]').forEach(function(el){var target=parseInt(el.dataset.count||'0',10);if(!target)return;var start=performance.now(),duration=650;function tick(now){var p=Math.min((now-start)/duration,1);el.textContent=Math.floor(target*(1-Math.pow(1-p,3))).toLocaleString();if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)})});</script>
